void near(double a,double b,double epsilon,const char* s){if(!std::isfinite(a) || std::abs(a-b)>epsilon)QTextStream(stderr)<<s<<": actual="<<a<<" expected="<<b<<'\n';check(std::isfinite(a) && std::abs(a-b)<=epsilon,s);}
