const ToolResult& result(const CycleResult& r,const QString& id){for(const auto& t:r.tools)if(t.toolId==id)return t;throw std::runtime_error("Missing result");}
double numeric(const ToolResult& t,const QString& port){const auto p=t.outputs.value(port);if(!p.valid)throw std::runtime_error((port+": "+t.message+" / "+p.invalidReason).toUtf8().constData());return std::get<double>(p.data);}
QJsonObject identity(const ActiveCalibrationSnapshot& s){return {{"contentId",s.selection.contentId},{"revision",s.selection.revision}};}
QPointF inversePlate(QPointF p){const double g=.0015,h=.0006,a=5-g*p.x(),b=.65-h*p.x(),c=p.x()-130,d=.2-g*p.y(),e=5.6-h*p.y(),f=p.y()-100;return {(c*e-b*f)/(a*e-b*d),(a*f-c*d)/(a*e-b*d)};}
